-- Append-only dataset versions (spec 02 §7, spec 10 §2.1): a snapshot row is never updated or
-- deleted, and a frozen version (its first run started) gets no new rows.
CREATE FUNCTION eval.sample_append_only() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS $$
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'eval.sample rows are immutable; create a new dataset version instead'
      USING ERRCODE = 'check_violation', CONSTRAINT = TG_NAME;
  END IF;
  IF EXISTS (SELECT 1 FROM eval.datasets d
              WHERE d.version = NEW.dataset_version AND d.frozen_at IS NOT NULL) THEN
    RAISE EXCEPTION 'dataset version % is frozen; a top-up creates the next version', NEW.dataset_version
      USING ERRCODE = 'check_violation', CONSTRAINT = TG_NAME;
  END IF;
  RETURN NEW;
END $$;--> statement-breakpoint
CREATE TRIGGER sample_append_only BEFORE INSERT OR UPDATE OR DELETE ON eval.sample
  FOR EACH ROW EXECUTE FUNCTION eval.sample_append_only();--> statement-breakpoint
-- A dataset version may be frozen once; afterwards it never changes and is never deleted.
CREATE FUNCTION eval.datasets_freeze_once() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.frozen_at IS NOT NULL THEN
      RAISE EXCEPTION 'a frozen dataset version is never deleted'
        USING ERRCODE = 'check_violation', CONSTRAINT = TG_NAME;
    END IF;
    RETURN OLD;
  END IF;
  IF OLD.frozen_at IS NOT NULL
     OR NEW.version <> OLD.version OR NEW.seed <> OLD.seed
     OR NEW.parent_version IS DISTINCT FROM OLD.parent_version
     OR NEW.created_at <> OLD.created_at THEN
    RAISE EXCEPTION 'a dataset version is immutable once frozen; only params and the freeze may change before'
      USING ERRCODE = 'check_violation', CONSTRAINT = TG_NAME;
  END IF;
  RETURN NEW;
END $$;--> statement-breakpoint
CREATE TRIGGER datasets_freeze_once BEFORE UPDATE OR DELETE ON eval.datasets
  FOR EACH ROW EXECUTE FUNCTION eval.datasets_freeze_once();--> statement-breakpoint
-- A run's identity and configuration are fixed when it starts; only its completion is recorded later.
CREATE FUNCTION eval.runs_config_immutable() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS $$
BEGIN
  IF NEW.id <> OLD.id OR NEW.experiment <> OLD.experiment
     OR NEW.dataset_version <> OLD.dataset_version OR NEW.config <> OLD.config
     OR NEW.git_sha <> OLD.git_sha OR NEW.started_at <> OLD.started_at THEN
    RAISE EXCEPTION 'an eval run''s experiment, dataset version and config are immutable'
      USING ERRCODE = 'check_violation', CONSTRAINT = TG_NAME;
  END IF;
  RETURN NEW;
END $$;--> statement-breakpoint
CREATE TRIGGER runs_config_immutable BEFORE UPDATE ON eval.runs
  FOR EACH ROW EXECUTE FUNCTION eval.runs_config_immutable();
